using System;
using System.IO;
using System.Linq;
using System.Collections;
using UnityEngine;
[Serializable] public class RoadMapTrialRequest {public string start,goal;}
public sealed class RoadMapTrialSession : MonoBehaviour {
 public RoadMapEditor editor;System.Diagnostics.Process child;string input,request;public bool Busy {get{return child!=null;}}public int? LastExitCode {get;private set;}
 public void Launch(RoadMapDocument d,string start,string goal){if(child!=null)throw new InvalidOperationException("시험 창이 이미 실행 중입니다");if(Application.isEditor)throw new InvalidOperationException("별도 시험 주행은 Windows 빌드에서 실행하세요");LastExitCode=null;string token=Guid.NewGuid().ToString("N");input=Path.Combine(Application.temporaryCachePath,"road-map-"+token+".json");request=input+".request.json";RoadMapStore.Save(input,d);File.WriteAllText(request,JsonUtility.ToJson(new RoadMapTrialRequest{start=start,goal=goal}));var info=new System.Diagnostics.ProcessStartInfo{FileName=System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName,Arguments="-eungye -roadMapTrial -roadMapInput \""+input+"\" -roadMapTrialRequest \""+request+"\" -screen-width 1600 -screen-height 900 -screen-fullscreen 0",UseShellExecute=false,WindowStyle=Array.IndexOf(Environment.GetCommandLineArgs(),"-roadMapEditorTest")>=0?System.Diagnostics.ProcessWindowStyle.Hidden:System.Diagnostics.ProcessWindowStyle.Normal};if(Array.IndexOf(Environment.GetCommandLineArgs(),"-roadMapEditorTest")>=0)info.Arguments+=" -roadMapTrialCheck";child=System.Diagnostics.Process.Start(info);}
 void Update(){if(child==null||!child.HasExited)return;int code=child.ExitCode;LastExitCode=code;child.Dispose();child=null;foreach(var path in new[]{input,request,input+".bak"})if(File.Exists(path))File.Delete(path);if(editor)editor.TrialReturned("시험 창 종료 "+code+" · 영업 기록 보존 · 초안 편집 계속 가능");}
 IEnumerator Start(){if(!RoadMapRuntime.Trial)yield break;yield return null;var s=GetComponent<DriveSession>();s.business.enabledCampaign=false;s.business.preparing=false;s.paused=false;Time.timeScale=1;s.roadConditions.enabled=false;string path=RoadMapRuntime.Argument("-roadMapTrialRequest");if(File.Exists(path)){var r=JsonUtility.FromJson<RoadMapTrialRequest>(File.ReadAllText(path));var graph=s.jobs.nav.hd;int start=Array.FindIndex(graph.edges,e=>e.id==r.start&&!e.disabled),goal=Array.FindIndex(graph.edges,e=>e.id==r.goal&&!e.disabled);if(start>=0){s.taxi.SetSpawn(graph.paths[start].Position(1)+Vector3.up*.65f,Quaternion.LookRotation(graph.paths[start].Tangent(1)));s.taxi.ResetTaxi();}if(goal>=0)s.jobs.nav.SetHdDestination(goal,Mathf.Max(1,graph.paths[goal].length-2));}s.jobs.enabled=false;if(Array.IndexOf(Environment.GetCommandLineArgs(),"-roadMapTrialCheck")>=0){yield return new WaitForSecondsRealtime(2);bool valid=RoadMapRuntime.Active!=null&&!s.business.enabledCampaign;string text="success="+valid+" revision="+s.world.map.editorRevision;File.WriteAllText(Path.GetFullPath("artifacts/road-map-editor/trial-child-test.txt"),text);Application.Quit(valid?0:1);}}
 void OnGUI(){if(!RoadMapRuntime.Trial)return;GUI.depth=-350;GUI.Box(new Rect(20,20,650,68),"지도 시험 · 영업/점수 저장 안 함 · "+RoadMapRuntime.Notice);if(GUI.Button(new Rect(35,55,220,25),"시험 종료 · 편집기로 돌아가기",KoreanText.Button(13)))Application.Quit();}
}
